// an L-shaped bracket, 30 wide, with a screw hole in each leg
const sk = sketch('top')
sk.polygon([[0, 0], [60, 0], [60, 10], [10, 10], [10, 40], [0, 40]])
const part = extrude(sk, 30)
hole(part, { across: 5, along: 'y', at: [10, 0] })
hole(part, { across: 5, along: 'x', at: [5, 0] })
round(part.edge('top', 'right'), 2)

// a small parts tray with one screw hole in the middle
const b = box(80, 50, 30)
hole(b, { across: 4, countersink: { across: 8, angle: 90 } })
hollow(b, { wall: 2, open: 'top' })

const b = box(80, 50, 30)
hollow(b, { wall: 2, open: 'top' })
hole(b, { across: 4, countersink: { across: 8, angle: 90 } })

const b = box(80, 50, 30)
hole(b, { across: 4 })
hollow(b, { wall: 2, open: 'top' })

// profile in (radius, height): bore 10, flange 40 across and 5 thick, sleeve 20 across and 25 tall
const sk = sketch('front', 0)
sk.polygon([[5, 0], [20, 0], [20, 5], [10, 5], [10, 25], [5, 25]])
const part = revolve(sk, 360)
hole(part, { across: 3, at: [15, 0] })
hole(part, { across: 3, at: [-15, 0] })
hole(part, { across: 3, at: [0, 15] })
hole(part, { across: 3, at: [0, -15] })

// a 50 x 30 plate drawn by hand and then dimensioned, 6 thick
const sk = sketch('top')
const plate = sk.rectangle([0.4, 0.3], [48, 31])
const big = sk.circle([34, 14], { r: 4.6 })
sk.at(plate.bottom.a, [0, 0])
sk.length(plate.bottom, 50)
sk.length(plate.right, 30)
sk.diameter(big, 10)
sk.dx(plate.bottom.a, big.c, 35)
sk.dy(plate.bottom.a, big.c, 15)
const part = extrude(sk, 6)
hole(part, { across: 4, at: [-15, 0] })
chamfer(part.edge('top', 'right'), 1)

// a cup with two sloped sides so it comes out of a mould
const b = box(60, 40, 25)
draft(b.face('right'), 5, { from: 'bottom' })
draft(b.face('left'), 5, { from: 'bottom' })
hollow(b, { wall: 2, open: 'top' })

