const b = box(80, 50, 30)
hole(b, { across: 4, countersink: { across: 8, angle: 90 } })
hollow(b, { wall: 2, open: 'bottom' })

const flange = cylinder(20, 5, { at: [0, 0, 2.5] })
const sleeve = cylinder(10, 25, { at: [0, 0, 12.5] })
const part = union(flange, sleeve)
hole(part, { across: 10 })
hole(part, { across: 3, at: [15, 0] })
hole(part, { across: 3, at: [-15, 0] })
hole(part, { across: 3, at: [0, 15] })
hole(part, { across: 3, at: [0, -15] })

